"""
	Retrieve indexes of the value in the nested list scalar.
	The index of the sublist corresponds to a K value.
	The index of the element corresponds to a kappa value.

	Parameters:
	scalar -- list, size 2^n x 2^n
	value  -- float
	"""
def find_idx_scalar(scalar: Any, value: Any) -> object {
    indexes = [
        [sublist_idx, elem_idx] for (sublist_idx, sublist) in enumerate(scalar)
        for (elem_idx, elem) in enumerate(sublist)
        if (elem == value)
    ];
    return indexes;
}

